functions.progLen:
int progLen(FILE *f)
{
    char c;
    int count = 0;
    for (c = getc(f); c != (-1); c = getc(f))
    {
        if (c == '\n')
        {
            count = count + 1;
        }
    }
    fseek(f, 0, 0);
    return count * 3;
}

functions.readline:
char *readline(FILE *file)
{
    const size_t default_len = 100;
    char *line = malloc(sizeof(char) * default_len);
    size_t len = default_len;
    size_t currentChar = 0;
    char c = '\0';
    while (c != -1)
    {
        c = fgetc(file);
        if (currentChar == len)
        {
            len *= 2;
            line = realloc(line, len);
        }
        if (c == '\n')
        {
            break;
        }
        line[currentChar] = c;
        currentChar++;
    }
    if (c == -1)
    {
        line[currentChar] = -1;
        currentChar++;
    }
    line[currentChar] = '\0';
    return line;
}

functions.parse:
struct sloth_program *parse(char *filepath)
{
    FILE *sFile;
    sFile = fopen(filepath, "r");
    if (sFile == ((void *)0))
    {
        fprintf(stderr, "[ERROR] File could not be opened.");
        exit(1);
    }
    int numCodes = progLen(sFile);
    ubyte *byteCode = malloc(sizeof(char) * numCodes);
    char c = '\0';
    size_t count = 0;
    char *line = 0x0;
    size_t len = 0;
    size_t codeNum = 0;
    unsigned char currentCode = 0;
    char hadToken = 0;
    while (1)
    {
        count = 0;
        currentCode = 0;
        line = readline(sFile);
        len = strlen(line);
        if (line[0] == -1)
        {
            free(line);
            break;
        }
        if (len == 0)
        {
            free(line);
            continue;
        }
        c = line[0];
        while (c != 0 && c != -1 && c != '#' && count <= len)
        {
            if (strncmp("slothy", line + count, 6) == 0)
            {
                byteCode[codeNum] = 0x1;
                codeNum++;
                count += 6;
                hadToken = 1;
            }
            else if (strncmp("sloth", line + count, 5) == 0)
            {
                currentCode++;
                count += 5;
                hadToken = 1;
            }
            else if (strncmp("and", line + count, 3) == 0)
            {
                byteCode[codeNum] = currentCode;
                codeNum++;
                currentCode = 0;
                count += 3;
                hadToken = 1;
            }
            else if (strncmp("nap", line + count, 3) == 0)
            {
                byteCode[codeNum] = 0x0;
                codeNum++;
                count += 3;
                hadToken = 1;
            }
            else
            {
                count++;
            }
            c = line[count];
        }
        if (hadToken)
        {
            byteCode[codeNum] = currentCode;
            codeNum++;
            hadToken = 0;
        }
        free(line);
    }
    struct sloth_program *S = malloc(sizeof(struct sloth_program));
    S->codes = byteCode;
    return S;
}

functions.execute:
int execute(struct sloth_program *sbin)
{
    sstack_t S = sstack_new();
    size_t pc = 0;
    ubyte *P = sbin->codes;
    _Bool run = 1;
    while (run)
    {
        switch (P[pc])
        {
        case EXIT: {
            if (sstack_empty(S))
            {
                sstack_free(S);
                return 0;
            }
            int x = spop(S);
            sstack_free(S);
            return x;
        }
        case ADD: {
            int b = spop(S);
            int a = spop(S);
            spush(S, a + b);
            pc++;
            break;
        }
        case SUB: {
            int b = spop(S);
            int a = spop(S);
            spush(S, a - b);
            pc++;
            break;
        }
        case MULT: {
            int b = spop(S);
            int a = spop(S);
            spush(S, a * b);
            pc++;
            break;
        }
        case DIV: {
            int b = spop(S);
            int a = spop(S);
            if (b == 0)
                mathErr("division by zero");
            if (a == (-0x7fffffff - 1) && b == -1)
                mathErr("division by zero");
            spush(S, a / b);
            pc++;
            break;
        }
        case COMP: {
            int b = spop(S);
            int a = spop(S);
            pc++;
            _Bool res = 0;
            switch (P[pc])
            {
            case EQ: {
                res = a == b;
                break;
            }
            case NEQ: {
                res = a != b;
                break;
            }
            case LT: {
                res = a < b;
                break;
            }
            case LE: {
                res = a <= b;
                break;
            }
            case GT: {
                res = a > b;
                break;
            }
            case GE: {
                res = a >= b;
                break;
            }
            default: {
                opErr("comparison", P[pc]);
            }
            }
            spush(S, (int)res);
            pc++;
            break;
        }
        case INP: {
            pc++;
            switch (P[pc])
            {
            case INT: {
                int x;
                printf(">");
                scanf("%d", &x);
                spush(S, x);
                break;
            }
            case CHR: {
                char x;
                scanf(">%c", &x);
                spush(S, (int)x);
                break;
            }
            default: {
                opErr("input type", P[pc]);
            }
            }
            pc++;
            break;
        }
        case OUT: {
            pc++;
            switch (P[pc])
            {
            case INT: {
                int x = spop(S);
                printf("%d", x);
                break;
            }
            case CHR: {
                char x = spop(S);
                printf("%c", x);
                break;
            }
            default: {
                opErr("output type", P[pc]);
            }
                pc++;
                break;
            }
            pc++;
            break;
        }
        case GOTO: {
            pc++;
            if (spop(S) == 1)
            {
                pc = P[pc];
            }
            else
            {
                pc++;
            }
            break;
        }
        case PUSH: {
            pc++;
            spush(S, P[pc]);
            pc++;
            break;
        }
        case DUP: {
            int x = spop(S);
            spush(S, x);
            spush(S, x);
            pc++;
            break;
        }
        default: {
            opErr("operation", P[pc]);
        }
        }
    }
    return 0;
}

functions.main:
int main(int argc, char **argv)
{
    if (argc != 2)
    {
        fprintf(stderr, "Usage: sloth <source file>\n");
        return 1;
    }
    char *fileName = argv[1];
    struct sloth_program *program = parse(fileName);
    int x = execute(program);
    printf("Returned: %d\n", x);
    freeProgram(program);
    return 0;
}

functions.mathErr:
void mathErr(char *msg)
{
    if (msg != ((void *)0))
        fprintf(stderr, "[ERROR] %s\n", msg);
    raise(8);
}

functions.opErr:
void opErr(char *type, uint8_t code)
{
    if (type != ((void *)0))
    {
        fprintf(stderr, "[ERROR] invalid %s code: 0x%02x\n", type, code);
    }
    raise(4);
}

structs.list_node:
struct list_node
{
    int data;
    struct list_node *next;
}

functions.sstack_new:
stack *sstack_new()
{
    stack *S = malloc(sizeof(stack));
    list *p = malloc(sizeof(list));
    S->top = p;
    S->bottom = p;
    return S;
}

functions.spush:
void spush(stack *S, int x)
{
    list *p = malloc(sizeof(list));
    p->data = x;
    p->next = S->top;
    S->top = p;
}

functions.spop:
int spop(stack *S)
{
    int x = S->top->data;
    list *q = S->top;
    S->top = S->top->next;
    free(q);
    return x;
}

functions.speek:
int speek(stack *S, int pos)
{
    list *l = S->top;
    for (; pos > 0; pos--)
    {
        l = l->next;
    }
    return l->data;
}

functions.sprint:
void sprint(stack *S)
{
    printf("|");
    list *l = S->top;
    while (l != S->bottom)
    {
        printf("%d ", l->data);
        l = l->next;
    }
    printf("\n");
}

functions.sstack_free:
void sstack_free(stack *S)
{
    while (S->top != S->bottom)
    {
        list *p = S->top;
        S->top = S->top->next;
        free(p);
    }
    free(S->top);
    free(S);
}
